 function updateMaterials(){if(!loaded)return;for(const m of loaded.meshes){const active=document.querySelector('#variant').value;const mapping=active===''?null:m.userData.variantMappings.find(v=>v.variants.includes(Number(active)));const materialIndex=mapping?mapping.material:m.userData.baseMaterial;applyMaterial(m.material,loaded.doc,loaded.textures,materialIndex,{textures:document.querySelector('#textures').checked,wireframe:document.querySelector('#wire').checked,sharp:document.querySelector('#sharp').checked});}for(const t of loaded.textures){t.flipY=document.querySelector('#flip').checked;t.needsUpdate=true;}}
-function showRecord(){if(!loaded)return;const n=recordSelect.value;for(const g of loaded.groups)g.visible=g.userData.record===n;const group=loaded.groups.find(g=>g.visible);if(!group)return;const box=new THREE.Box3().setFromObject(group);if(box.isEmpty()){status.textContent=`${selected.code} · ${sceneLabel(group.userData.label||n)} · no drawable geometry in this source tree`;return;}const center=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3()),extent=Math.max(size.x,size.y,size.z,.1);controls.target.copy(center);camera.position.copy(center).add(new THREE.Vector3(extent*.95,extent*.55,extent*.95));camera.near=Math.max(extent/10000,.0001);camera.far=extent*100;camera.updateProjectionMatrix();controls.update();updateMaterials();const glass=shownMeshes(group).filter(m=>m.userData.headerColour);const glassNote=glass.length?` · glass/Header-colour parts (${glass.length} here) draw the original stored colour and GS alpha (opacity alpha/128); the mapping is a candidate, not proven shading`:'';const r=selected.records.find(r=>String(r.record)===n);const label=group.userData.label?sceneLabel(group.userData.label):`assembly part ${n} (${r.triangles.toLocaleString()} candidate triangles)`;status.textContent=`${selected.code} · ${label} · size ${size.toArray().map(v=>v.toFixed(2)).join(' × ')} (game units) · exported source scene; runtime rendering fidelity remains under validation${glassNote}`;}
