 function isShown(mesh){for(let node=mesh;node;node=node.parent){if(node.visible===false)return false;}return true;}
 function shownMeshes(root){const found=[];if(!root||root.visible===false)return found;root.traverse(o=>{if(o.isMesh)found.push(o);});return found;}
 function updateDescription(entry){const node=document.querySelector('#source-description');if(!node)return;node.textContent=entry.game==='ford-racing-2'?'Ford Racing 2: original coordinates with candidate triangle assembly, normals and shading. Tree presets follow recovered visibility routines; live LOD and runtime fidelity remain under validation.':entry.game==='gran-turismo'?'Gran Turismo: native car and texture conversions, identified by source archive codes. Day, night and arcade exports remain separate. Retail display names and game-render fidelity are unverified.':entry.game==='redline'?'Redline: native car configurations with converted static models and embedded textures. Base and add-on variants remain separate. Names come from source configurations; game-render fidelity is unverified.':entry.game==='midnight-club-3-remix'?'Midnight Club 3 Remix: recovered native PS2 vehicle packages. 3D previews are unavailable.':entry.game==='midnight-club-los-angeles'?'Midnight Club: Los Angeles: static stock-index assemblies with decoded diffuse textures. Native source packages remain available as ZIPs; runtime customization, paint and game-render fidelity remain unverified.':entry.game==='gran-turismo-4'?'Gran Turismo 4: static showroom models decoded from native CAR4 files, with embedded textures and retail names from the game\'s spec database. The native files remain available as a ZIP.':'Recovered source model; inspect its exported scenes and textures. Runtime rendering fidelity is unverified.';if(entry.claim_limits?.length)node.textContent+=' '+entry.claim_limits.join(' ');}

